                //狄仁杰-20220317吃朵棉花糖
                ywhy_qian: {
                    audio: 'ext:金庸群侠传/peiyin:8',
                    trigger: { global: 'damageBefore' },
                    forced: true,
                    firstDo: true,
                    popup: false,
                    filter(event, player) {
                        return event.source && event.source.isIn();
                    },
                    content() {
                        ///这个方法是删掉伤害来源 并再此事件算完后再为这个事件找一个来源
                        ///此方法修改不能触发来源造成伤害加伤害 受伤角色不能刚烈反馈 因为没有来源
                        delete trigger.source;
                        var next = game.createEvent('damage_init');
                        next._trigger = trigger;
                        event.next.remove(next);
                        trigger.after.push(next);
                        next.setContent(function () {
                            if (trigger.source && get.itemtype(trigger.source) == 'player') return; //若此事件因其他技能找到了来源,则跳过
                            if (trigger.player.getHistory('damage').includes(trigger)) {
                                //若此事件 不因技能取消掉//则执行以下内容
                                var players = game.filterPlayer();
                                var source = players.randomGet();
                                source.getHistory('sourceDamage').push(trigger);
                                if (source.stat[source.stat.length - 1].damage == undefined) {
                                    source.stat[source.stat.length - 1].damage = trigger.num;
                                } else {
                                    source.stat[source.stat.length - 1].damage += trigger.num;
                                }
                                trigger.source = source;
                            }
                        });
                    },
                },
