                    getResult(cards, bool) {
                        var l = cards.length;
                        var all = Math.pow(l, 2);
                        var list = [];
                        for (var i = 1; i < all; i++) {
                            var array = [];
                            for (var j = 0; j < l; j++) {
                                if (Math.floor((i % Math.pow(2, j + 1)) / Math.pow(2, j)) > 0) array.push(cards[j]);
                            }
                            var num = 0;
                            for (var k of array) {
                                num += k.number;
                            }
                            if (num > 0 && num % 9 == 0) list.push(array);
                        }
                        if (list.length) {
                            if (bool) return true;
                            list.sort(function (a, b) {
                                if (a.length != b.length) return b.length - a.length;
                                return get.value(a) - get.value(b);
                            });
                            var list2 = [];
                            for (var i = 0; i < list.length; i++) {
                                var posinst = {
                                    hs: [],
                                    es: [],
                                    js: [],
                                };
                                posinst.cards = list[i];
                                for (var j = 0; j < list[i].length; j++) {
                                    if (get.position(list[i][j]) == 'h') {
                                        posinst.hs.push(list[i][j]);
                                    } else if (get.position(list[i][j]) == 'e') {
                                        posinst.es.push(list[i][j]);
                                    } else {
                                        posinst.js.push(list[i][j]);
                                    }
                                }
                                list2.push(posinst);
                            }
                            return list2;
                        }
                        return false;
                        //return list;
                    },
